// =====================================================================================
//  Member Contract, Graduation & Dismissal · Birthdays
// -------------------------------------------------------------------------------------
//  · Contract (m.ct): Fixed-term (N years from the joining date) or Age-based (until age N). Set at the
//    audition (S.ct.def), applied to every recruit. Existing members get a 5-year contract from joining.
//    3 months before expiry the member and the Producer talk (intention: renew / graduate / undecided).
//    Renewal: the Producer proposes a duration, the member accepts or refuses. No renewal limit; every
//    contract and renewal is kept in m.ct.hist. No renewal → normal graduation at the contract end.
//  · Contract status: Active, Graduation Announced, Contract Expiring, Contract Renewal, Graduated,
//    Agency Retained, Dismissed.
//  · Graduation (m.grad): member request, Producer proposal (the member must agree) or contract expiry.
//    Announced to the fans; the member stays active ~90 days (target date) and graduates at her
//    Graduation Stage (mandatory, spstage.js). Early graduation before the contract end: A) contract
//    termination fee (by remaining duration; she is then free) or B) Agency Retained (no entertainment
//    work until the contract end).
//  · Graduation Song (song.gradFor) / Graduation Single (single.gradFor) — the member is the Center,
//    released before the graduation date. Graduation costume made in the Costume Studio (final profile).
//  · Dismissal: reason, Immediate or with a Graduation Stage, compensation if unjustified (Company
//    Money, Finance History), fan reaction (fan loss, lower single sales for a while, criticism).
//  · Career one month after leaving (m.career); Solo Idol / New Idol Group acts (S.ct.acts) with their own
//    singles, MVs, covers, fans and sales — no teams, theater, elections or sister management.
//  · Birthdays (m.bd): age +1 on the birthday (once a year), notice 7 days ahead. No stat effects.
// =====================================================================================
const CT_ST={act:'Active',ann:'Graduation Announced',exp:'Contract Expiring',ren:'Contract Renewal',grad:'Graduated',ret:'Agency Retained',dis:'Dismissed'};
const CT_DR={rules:'Violation of Company Rules',misc:'Repeated Misconduct',cv:'Contract Violation',pers:'Personal Circumstances',oth:'Other'},CT_JUST=new Set(['rules','misc','cv']);
const CT_CAR={ret:'Retired',ind:'Independent / Freelance',new:'New Career',ag:'Joined Another Agency',solo:'Solo Idol',grp:'New Idol Group',und:'Undisclosed'};
const CT_GR={req:'Member request',prop:'Producer proposal',exp:'Contract expiry',dis:'Dismissal'};
const CT_MON=['January','February','March','April','May','June','July','August','September','October','November','December'];
let CTQ=[];
function ctS(){if(!S.ct)S.ct={def:{type:'fixed',yrs:5,age:25},log:[],acts:[],seq:0,boy:null};const C=S.ct;C.def=C.def||{type:'fixed',yrs:5,age:25};C.log=C.log||[];C.acts=C.acts||[];return C}
const ctMem=id=>get(id)||(S.alumni||[]).find(a=>a.id==id)||null;
const ctY=d=>dayDate(d).getFullYear();
const ctAddY=(d,n)=>{const t=dayDate(d);return dateDay(new Date(t.getFullYear()+n,t.getMonth(),t.getDate()))};
const ctPay=m=>200000+Math.round(m.pop||0)*5000; // estimated monthly value of a member's activities
const ctMonths=(a,b)=>Math.max(0,Math.ceil((b-a)/30));
function ctLog(m,t,txt){ctS().log.unshift({day:S.day,mid:m?m.id:null,name:m?m.name:'',t,txt});if(S.ct.log.length>300)S.ct.log.length=300}
// ---- birthdays -----------------------------------------------------------------------------------------------------
const ctBdDay=(m,y)=>dateDay(new Date(y,m.bd.mo-1,m.bd.d));
function ctBdEnsure(m){if(!m||m.bd&&m.bd.mo)return;const mo=rnd(1,12),d=rnd(1,[31,28,31,30,31,30,31,31,30,31,30,31][mo-1]);m.bd={mo,d};const Y=ctY(S.day),past=ctBdDay(m,Y)<=S.day;m.bd.y=Y-(m.age||18)-(past?0:1);m.bdY=past?Y:Y-1}
function ctNextBd(m){ctBdEnsure(m);const Y=ctY(S.day);let d=ctBdDay(m,Y);if(d<S.day)d=ctBdDay(m,Y+1);return d}
function ctPrevBd(m){ctBdEnsure(m);const Y=ctY(S.day);let d=ctBdDay(m,Y);if(d>S.day)d=ctBdDay(m,Y-1);return d}
const ctBdTxt=m=>m&&m.bd?`${CT_MON[m.bd.mo-1]} ${m.bd.d}${m.bd.y?', '+m.bd.y:''}`:'—';
function ctBdSet(mid){const m=get(mid);if(!m)return;const mo=+($('#ctbm')||{}).value,d=+($('#ctbd')||{}).value;if(!(mo>=1&&mo<=12&&d>=1&&d<=31))return toast('Choose a month and a day.','err');const max=[31,29,31,30,31,30,31,31,30,31,30,31][mo-1];if(d>max)return toast('That day does not exist in that month.','err');
 m.bd={mo,d:mo==2&&d==29?28:d};const Y=ctY(S.day),past=ctBdDay(m,Y)<=S.day;m.bd.y=Y-m.age-(past?0:1);m.bdY=past?Y:Y-1;m.bdN=null;if(m.ct&&m.ct.type=='age')m.ct.end=ctAgeEnd(m,m.ct.age);toast(`Birthday set: ${ctBdTxt(m)}.`);render()}
// ---- contracts -------------------------------------------------------------------------------------------------------
const ctAgeEnd=(m,age)=>{ctBdEnsure(m);return ctBdDay(m,m.bd.y+age)};
function ctTerm(m,c,start){return c.type=='age'?ctAgeEnd(m,c.age):ctAddY(start,c.yrs)}
const ctTermTxt=c=>c?(c.type=='age'?`Age-based · until age ${c.age}`:`Fixed-term · ${c.yrs} year${c.yrs>1?'s':''}`):'—';
function ctEnsure(m){if(!m)return;ctBdEnsure(m);if(m.ct&&m.ct.end!=null)return;const st=m.joined||0;let end=ctAddY(st,5),y=5;while(end<S.day+180){y++;end=ctAddY(st,y)}
 m.ct={type:'fixed',yrs:y,start:st,end,hist:[{day:st,kind:'sign',type:'fixed',yrs:y,start:st,end,auto:1}],talk:null,next:null}}
function ctSign(m,def){ctBdEnsure(m);const c=def||ctS().def,st=m.joined??S.day;let end=ctTerm(m,c,st);if(c.type=='age'&&end<=S.day+365){end=ctAddY(S.day,3)}
 m.ct={type:c.type,yrs:c.yrs,age:c.age,start:st,end,hist:[{day:S.day,kind:'sign',type:c.type,yrs:c.yrs,age:c.age,start:st,end}],talk:null,next:null};hev(m,{t:'ct_sign',txt:ctTermTxt(c),end});ctLog(m,'sign',`Contract signed: ${ctTermTxt(c)} (until ${longDate(end)})`)}
function ctStatus(m){if(!m)return'act';if(m.status=='graduated'||!S.members.includes(m)){const D=m.dep||{};if(D.kind=='dismiss')return'dis';if(D.ret&&m.ct&&S.day<m.ct.end)return'ret';return'grad'}
 if(m.grad)return'ann';const c=m.ct;if(c&&c.next)return'ren';if(c&&c.end-S.day<=90)return'exp';return'act'}
const ctStTag=m=>{const k=ctStatus(m);return`<span class="tag ctst ctst-${k}">${CT_ST[k]}</span>`};
function ctIntent(m){const v=m.loy*.35+m.mor*.25+m.pas*.3+(m.age<=21?10:m.age>=27?-14:0)+rnd(-15,15);return v>62?'renew':v<42?'grad':'und'}
const CT_INT={renew:'wants to renew her contract',grad:'is thinking about graduating',und:'is undecided'};
// ---- renewal talk ----------------------------------------------------------------------------------------------------
function ctTalkHtml(m){const c=m.ct,t=c.talk||{},Y=[1,2,3,4,5,6],ages=[];for(let a=m.age+1;a<=Math.max(m.age+12,35);a++)ages.push(a);
 const said={renew:`“I want to keep going with the group. I'd like to renew my contract.”`,grad:`“I've been thinking about my future… I think it might be time for me to graduate.”`,und:`“I haven't decided yet. I want to hear what you think, Producer.”`}[t.int]||'';
 return`<h2 class="ht">📄 Contract talk — ${esc(m.name)}</h2><div class="fbrow">${ptc(m,56)}<div><b>${esc(m.stage||m.name)}</b><div class="st">${ctTermTxt(c)} · ends ${longDate(c.end)} (${Math.max(0,c.end-S.day)} days)</div></div></div>
 <p class="ctsay">${said}</p><p class="st">${esc(m.name)} ${CT_INT[t.int]||''}.${(t.tries||0)?` Renewal proposals refused so far: ${t.tries}.`:''}</p>
 <h3>Propose a renewal</h3><div class="row"><label class="st">Type <select id="ctrt"><option value="fixed">Fixed-term</option><option value="age">Age-based</option></select></label><label class="st">Years <select id="ctry">${Y.map(n=>`<option ${n==3?'selected':''}>${n}</option>`).join('')}</select></label><label class="st">or until age <select id="ctra">${ages.map(a=>`<option>${a}</option>`).join('')}</select></label><button class="b p" onclick="ctRenew(${m.id})">Propose renewal</button></div>
 <h3>Or</h3><div class="row"><button class="b" onclick="ctGradDlg(${m.id},'exp')">🎓 Accept graduation at the contract end</button><button class="b s" onclick="ui.mod=null;render()">Decide later</button></div><p class="st">Undecided contracts: graduation is announced automatically 60 days before the end.</p>`}
function ctTalkOpen(mid){const m=get(mid);if(!m||!m.ct||!m.ct.talk)return;ui.mod={t:'html',h:ctTalkHtml(m)};render()}
function ctRenew(mid){const m=get(mid);if(!m||!m.ct)return;const c=m.ct,t=c.talk||(c.talk={day:S.day,end:c.end,int:ctIntent(m)}),type=$('#ctrt').value,yrs=+$('#ctry').value,age=+$('#ctra').value;
 const nc={type,yrs:type=='fixed'?yrs:null,age:type=='age'?age:null},end=type=='age'?ctAgeEnd(m,age):ctAddY(c.end,yrs),len=(end-c.end)/365;if(end<=c.end)return toast('The new contract must end after the current one.','err');
 const p=cl(({renew:.92,und:.6,grad:.18}[t.int]||.5)+(len>=5?-.12:len<=2?.06:0)-(t.tries||0)*.08,.03,.97);
 if(Math.random()<p){c.next={...nc,start:c.end,end,day:S.day};c.hist.push({day:S.day,kind:'renew',type,yrs:nc.yrs,age:nc.age,start:c.end,end});t.res='renew';hev(m,{t:'ct_renew',txt:ctTermTxt(nc),end});ctLog(m,'renew',`Contract renewed: ${ctTermTxt(nc)} (until ${longDate(end)})`);
  ui.mod={t:'html',h:`<h2 class="ht">🤝 ${esc(m.name)} renews her contract</h2><p class="ctsay">“Thank you, Producer. I'll keep doing my best!”</p><p class="st">New contract: ${ctTermTxt(nc)} · starts ${longDate(c.end)} · ends ${longDate(end)}.</p>`}}
 else{t.tries=(t.tries||0)+1;m.mor=cl(m.mor-3);if(t.int=='und'&&t.tries>=2)t.int='grad';ctLog(m,'refuse','Refused a renewal proposal');toast(`${m.name} did not accept that proposal.`,'err');ui.mod={t:'html',h:ctTalkHtml(m)}}render()}
// ---- graduation announcement ------------------------------------------------------------------------------------------
function ctAgreeP(m){const t=m.ct&&m.ct.talk;return cl(.3+(m.age-20)*.04+(60-m.pas)/150+(60-m.mor)/250+(t&&t.int=='grad'?.4:0)+(m.req?.6:0),.05,.97)}
function ctGradDlg(mid,why){const m=get(mid);if(!m)return;if(m.grad)return toast(`${m.name}'s graduation is already announced (${longDate(m.grad.target)}).`,'err');ctEnsure(m);const c=m.ct;
 const D=ui.ctd&&ui.ctd.mid==mid?ui.ctd:(ui.ctd={mid,why:why||(m.req?'req':c.talk&&c.talk.res!='renew'&&c.end-S.day<=90?'exp':'prop'),days:90,early:'ret'});if(why)D.why=why;
 const target=D.why=='exp'?Math.max(S.day+14,c.end):S.day+D.days,early=target<c.end-30,mo=ctMonths(target,c.end),fee=Math.round(mo*ctPay(m));
 const box=`<h2 class="ht">🎓 Graduation — ${esc(m.name)}</h2><div class="fbrow">${ptc(m,56)}<div><b>${esc(m.stage||m.name)}</b><div class="st">${ctTermTxt(c)} · contract ends ${longDate(c.end)}</div></div></div>
 <div class="row"><label class="st">Reason <select onchange="ui.ctd.why=this.value;ctGradDlg(${mid})">${['req','prop','exp'].map(k=>`<option value="${k}" ${D.why==k?'selected':''} ${k=='req'&&!m.req?'disabled':''}>${CT_GR[k]}${k=='req'&&!m.req?' (she has not asked)':''}</option>`).join('')}</select></label>
 ${D.why!='exp'?`<label class="st">Activities continue for <select onchange="ui.ctd.days=+this.value;ctGradDlg(${mid})">${[30,45,60,75,90].map(n=>`<option value="${n}" ${D.days==n?'selected':''}>${n} days</option>`).join('')}</select></label>`:''}</div>
 <p class="st">Graduation date: <b>${longDate(target)}</b> at the latest. She keeps all activities until then and graduates at her <b>Graduation Stage</b> (required — a Theater performance of her team on or before that date; it can be earlier).</p>
 ${D.why=='prop'?`<p class="st">This is your proposal: ${esc(m.name)} must agree (about ${Math.round(ctAgreeP(m)*100)}% chance). If she refuses, you can propose again after 30 days.</p>`:''}
 ${early?`<div class="c"><h3>Early graduation · ${mo} month(s) before the contract end</h3><label class="ctopt"><input type="radio" name="cte" ${D.early=='fee'?'checked':''} onchange="ui.ctd.early='fee';ctGradDlg(${mid})"> <b>A) Contract termination fee</b> — ${yen(fee)} (${mo} remaining month(s)). The contract ends at graduation and she is free.</label><label class="ctopt"><input type="radio" name="cte" ${D.early=='ret'?'checked':''} onchange="ui.ctd.early='ret';ctGradDlg(${mid})"> <b>B) Agency Retained</b> — she graduates from the group but stays under contract until ${longDate(c.end)}, without any entertainment work.</label></div>`:''}
 <div class="row"><button class="b p" onclick="ctGradGo(${mid})">📣 Announce graduation</button><button class="b s" onclick="ui.ctd=null;ui.mod=null;render()">Cancel</button></div>`;
 ui.mod={t:'html',h:box};render()}
function ctGradGo(mid){const m=get(mid),D=ui.ctd;if(!m||!D)return;const c=m.ct;if(D.why=='prop'){if(m.ctProp!=null&&S.day-m.ctProp<30)return toast(`${m.name} refused recently. Propose again after ${jd(m.ctProp+30)}.`,'err');
  if(Math.random()>ctAgreeP(m)){m.ctProp=S.day;m.mor=cl(m.mor-6);hev(m,{t:'ct_gprop_no'});ctLog(m,'gprop','Refused a graduation proposal');ui.ctd=null;ui.mod={t:'html',h:`<h2 class="ht">${esc(m.name)} wants to stay</h2><p class="ctsay">“I'm sorry, Producer… I'm not ready to graduate yet. I still want to perform with everyone.”</p><p class="st">She did not agree. You can propose again after ${jd(S.day+30)}.</p>`};return render()}}
 const target=D.why=='exp'?Math.max(S.day+14,c.end):S.day+D.days,early=target<c.end-30;ctAnnounce(m,{reason:D.why,target,early:early?D.early:null});ui.ctd=null;render()}
function ctAnnounce(m,o){const c=m.ct,mo=ctMonths(o.target,c.end);m.grad={ann:S.day,reason:o.reason,target:o.target,early:o.early||null,fee:o.early=='fee'?Math.round(mo*ctPay(m)):0,kind:o.kind||'grad',dis:o.dis||null,stage:null,cz:null,songs:[],singles:[]};m.req=null;if(c.talk)c.talk.res='grad';
 m.buzz=cl((m.buzz||0)+12);hev(m,{t:'ct_ann',reason:CT_GR[o.reason]||o.reason,target:o.target,early:o.early||null});ctLog(m,'ann',`${o.kind=='dismiss'?'Dismissal announced':'Graduation announced'} (${CT_GR[o.reason]||o.reason}) · until ${longDate(o.target)}${o.early=='fee'?' · termination fee':o.early=='ret'?' · Agency Retained':''}`);
 const h=ctAnnHtml(m);if(o.quiet)CTQ.push(h);else ui.mod={t:'html',h};return m.grad}
function ctAnnHtml(m){const G=m.grad,t=teamOf(m),dis=G.kind=='dismiss';return`<div class="ctann"><div class="gekicker">${dis?'Announcement':'Graduation Announcement'}</div><div class="fbrow">${ptc(m,72)}<div><h2 class="ht">${esc(m.stage||m.name)}</h2><div class="st">${esc(gn(m.group))}${t&&isAct(m)?' · '+esc(t.name):' · '+esc(TLm(m))} · ${ord(m.gen||1)} Generation</div></div></div>
 ${dis?`<p>The agency announced that <b>${esc(m.name)}</b>'s activities with ${esc(gn(m.group))} will end (${esc(CT_DR[G.dis.reason]||'')}). Her final performance is her Graduation Stage, on or before ${longDate(G.target)}.</p>`:`<p><b>${esc(m.name)}</b> announced her graduation from ${esc(gn(m.group))}. Her last day of activities is <b>${longDate(G.target)}</b> at the latest; she graduates at her Graduation Stage.</p><p class="ctsay">“Thank you for always supporting me. I'll give everything until the very last day!”</p>`}
 <p class="st">Reason: ${esc(CT_GR[G.reason]||G.reason)} · announced ${longDate(G.ann)}${G.early=='fee'?` · contract termination fee ${yen(G.fee)} (booked at graduation)`:G.early=='ret'?` · Agency Retained until ${longDate(m.ct.end)}`:''}</p>
 <p class="st">Fans reacted strongly: her name trended all day and buzz around her rose. Plan her Graduation Stage and Graduation Costume in her profile (Contract &amp; Graduation).</p><div class="row"><button class="b s p" onclick="ui.mod=null;ui.ptab='stats';ui.mod={t:'prof',id:${m.id}};render()">Open profile</button></div></div>`}
// ---- leaving the group (graduation stage done / immediate dismissal) --------------------------------------------------------
function ctLeave(m){const mid=m.id;let R=null;try{R=fbGraduate(mid)}catch(e){console.error(e)}const t=teamOf(m);if(t)hev(m,{t:'team_leave',tid:t.id,tname:t.name});setTeamOf(m,null);m.status='graduated';m.gradDay=S.day;
 try{gsWith(gsGid(m),()=>{if(S.pj&&S.pj.status=='draft')[S.pj.mainId,...(S.pj.coup||[])].forEach(i=>{const o=S.songs[i];if(o&&o.fm){let ch=0;o.fm.sl.forEach(x=>{if(x.m==mid){x.m=null;ch=1}});if(ch)fmSync(o)}})})}catch(e){console.error(e)}
 (S.cal||[]).forEach(e=>{if(!e.done&&Array.isArray(e.members))e.members=e.members.filter(x=>x!=mid)});S.alumni=S.alumni||[];if(!S.alumni.includes(m))S.alumni.push(m);S.members=S.members.filter(x=>x.id!=mid);try{leadFix(true)}catch(e){}try{svCleanRefs()}catch(e){}return R}
function ctComplete(m,o){o=o||{};const G=m.grad||{},c=m.ct||{},dis=G.kind=='dismiss'||o.dismiss;
 if(G.cz){const d=czD(G.cz);if(d){m.czHist=m.czHist||[];if(m.profCz)m.czHist.push(m.profCz);m.profCz={p:czClone(d.p),title:'Graduation costume',kind:'grad',did:d.id,day:S.day};m.gradCz={did:d.id,name:d.name,day:S.day}}}
 const R=ctLeave(m);hev(m,{t:dis?'ct_dis_done':'graduate'});
 m.dep={kind:dis?'dismiss':'grad',day:S.day,reason:G.reason,ann:G.ann,target:G.target,early:G.early,fee:G.fee||0,ret:G.early=='ret',dis:G.dis||o.dis||null,stage:o.rec||null,songs:G.songs||[],singles:G.singles||[]};
 if(G.early=='fee'&&G.fee>0){earn(G.fee,`Contract termination fee: ${m.name}`);c.term=S.day;c.hist&&c.hist.push({day:S.day,kind:'term',fee:G.fee,end:S.day});ctLog(m,'fee',`Contract terminated early · fee ${yen(G.fee)} (Finance History)`)}
 if(G.early=='ret'){c.hist&&c.hist.push({day:S.day,kind:'ret',end:c.end});hev(m,{t:'ct_ret',end:c.end});ctLog(m,'ret',`Agency Retained until ${longDate(c.end)}`)}
 m.career={due:(G.early=='ret'?Math.max(c.end,S.day):S.day)+30,v:null};delete m.grad;
 ctLog(m,dis?'dis':'grad',dis?`Dismissed${o.rec?' after her Graduation Stage':' (immediate)'}`:`Graduated${o.rec?' at her Graduation Stage':''}`);
 CTQ.push(`<h2 class="ht">${dis?'🚪':'🎓'} ${esc(m.name)} ${dis?'has left the group':'has graduated'}</h2><div class="fbrow">${pt(m,80)}<div><b>${esc(m.stage||m.name)}</b><div class="st">${CT_ST[ctStatus(m)]} · ${longDate(S.day)}${m.gradCz?` · final profile costume: ${esc(m.gradCz.name)}`:''}</div></div></div>${R?fbGradHtml(R).replace(/<h2[^>]*>[\s\S]*?<\/h2>/,''):''}`);return R}
// ---- dismissal -----------------------------------------------------------------------------------------------------------
function ctDisCalc(m,reason){ctEnsure(m);const just=CT_JUST.has(reason),mo=ctMonths(S.day,m.ct.end),comp=just?0:Math.round(mo*ctPay(m)*(1+(m.pop||0)/200)*(reason=='pers'?.8:1)),p=(m.pop||0)/100;
 return{just,mo,comp,loss:just?.01+.02*p:.03+.06*p,mult:just?1-(.02+.04*p):1-(.06+.12*p),days:90+(p>.7?60:0),crit:!just}}
function ctDisDlg(mid){const m=get(mid);if(!m)return;if(m.grad&&m.grad.kind=='dismiss')return toast('A dismissal is already announced.','err');const D=ui.ctdis&&ui.ctdis.mid==mid?ui.ctdis:(ui.ctdis={mid,reason:'rules',how:'now',note:''}),X=ctDisCalc(m,D.reason);
 ui.mod={t:'html',h:`<h2 class="ht">🚪 Dismissal — ${esc(m.name)}</h2><div class="fbrow">${ptc(m,56)}<div><b>${esc(m.stage||m.name)}</b><div class="st">${ctTermTxt(m.ct)} · ends ${longDate(m.ct.end)} · popularity ${m.pop}</div></div></div>
 <div class="row"><label class="st">Reason <select onchange="ui.ctdis.reason=this.value;ctDisDlg(${mid})">${Object.entries(CT_DR).map(([k,n])=>`<option value="${k}" ${D.reason==k?'selected':''}>${n}</option>`).join('')}</select></label><label class="st">Method <select onchange="ui.ctdis.how=this.value;ctDisDlg(${mid})"><option value="now" ${D.how=='now'?'selected':''}>Immediate dismissal (no stage)</option><option value="stage" ${D.how=='stage'?'selected':''}>Dismissal with a Graduation Stage</option></select></label></div>
 <div class="fbkv"><div><small>Compensation</small><b>${X.comp?yen(X.comp):'None'}</b></div><div><small>Estimated fan loss</small><b>${(X.loss*100).toFixed(1)}%</b></div><div><small>Single sales for ${X.days} days</small><b>−${Math.round((1-X.mult)*100)}%</b></div></div>
 <p class="st">${X.just?'A justified dismissal (serious misconduct or contract violation): no compensation is due, and fans react less strongly.':`An unjustified dismissal: the agency pays compensation (${X.mo} remaining month(s), pay and popularity) from Company Money, and fans criticise the decision — some boycott upcoming singles.`} ${D.how=='stage'?'She keeps performing until her Graduation Stage (within 60 days), then her status becomes Dismissed.':'Her status becomes Dismissed immediately.'}</p>
 <div class="row"><button class="b p" onclick="ctDisGo(${mid})">Confirm dismissal</button><button class="b s" onclick="ui.ctdis=null;ui.mod=null;render()">Cancel</button></div>`};render()}
function ctDisGo(mid){const m=get(mid),D=ui.ctdis;if(!m||!D)return;const X=ctDisCalc(m,D.reason),dis={reason:D.reason,how:D.how,day:S.day,comp:X.comp,just:X.just,loss:0,mult:X.mult};
 if(X.comp>0){S.money-=X.comp;S.exp+=X.comp;S.led.unshift({d:S.day,l:`Dismissal compensation: ${m.name}`,a:-X.comp});S.led.length=Math.min(S.led.length,80);m.ct.hist.push({day:S.day,kind:'comp',fee:X.comp})}
 dis.loss=ctFanLoss(X.loss,m.id,'Dismissal');const B=ctS();B.boy={mult:Math.min(X.mult,B.boy&&B.boy.until>=S.day?B.boy.mult:1),until:S.day+X.days,why:m.name};
 if(X.crit)S.members.filter(x=>x.id!=m.id&&x.group==m.group).forEach(x=>{x.mor=cl(x.mor-3)});
 hev(m,{t:'ct_dis',reason:CT_DR[D.reason],how:D.how,comp:X.comp});ctLog(m,'dis',`Dismissal: ${CT_DR[D.reason]} · ${D.how=='now'?'immediate':'with a Graduation Stage'}${X.comp?' · compensation '+yen(X.comp):''} · fans −${dis.loss.toLocaleString()}`);ui.ctdis=null;
 const rep=`<div class="c"><h3>Fan reaction</h3><ul class="ms"><li>${dis.loss.toLocaleString()} fans left the group.</li><li>Upcoming single sales −${Math.round((1-X.mult)*100)}% until ${longDate(S.day+X.days)}${X.crit?' (boycott)':''}.</li>${X.crit?'<li>Fans and media criticised the agency; members of the group are shaken (morale −3).</li>':'<li>Most fans accepted the decision.</li>'}${X.comp?`<li>Compensation paid: ${yen(X.comp)} (Finance History).</li>`:''}</ul></div>`;
 if(D.how=='now'){m.grad={ann:S.day,reason:'dis',target:S.day,kind:'dismiss',dis,early:null,fee:0,songs:[],singles:[]};ctComplete(m,{dismiss:1,dis});ui.mod={t:'html',h:CTQ.pop()+rep};CTQ=CTQ.slice()}
 else{ctAnnounce(m,{reason:'dis',target:S.day+60,kind:'dismiss',dis,quiet:1});ui.mod={t:'html',h:CTQ.pop()+rep}}render()}
function ctFanLoss(rate,mid,why){try{const fb=S.fb;if(!fb||!fb.segs){const n=Math.round((S.fans||0)*rate);S.fans=Math.max(0,(S.fans||0)-n);return n}let L=0;fb.segs.forEach(s=>{const r=s.k==mid?Math.min(.6,rate*4):rate,n=Math.round(s.n*r);s.n-=n;L+=n});fb.acc.lost+=L;fb.acc.lossBy[why]=(fb.acc.lossBy[why]||0)+L;fbApply();return L}catch(e){console.error(e);return 0}}
// lower single sales while fans boycott (applied to the demand of singles released in that period)
{const f=doRelease;doRelease=function(){const n=S.singles.length;const r=f.apply(this,arguments);try{const B=S.ct&&S.ct.boy,x=S.singles[n];if(x&&B&&S.day<=B.until&&B.mult<1){x.boy={mult:B.mult,why:B.why};if(x.dem)x.dem=Math.round(x.dem*B.mult);if(x.sale)x.sale.eds.forEach(e=>{if(e.F)e.F*=B.mult;if(e.P)e.P*=B.mult});else if(x.sales){x.sales=Math.round(x.sales*B.mult)}}}catch(e){console.error(e)}return r}}
