function ctReqHtml(m){return`<h2 class="ht">💬 ${esc(m.name)} wants to talk</h2><div class="fbrow">${ptc(m,64)}<div><p class="ctsay">“Producer… I've thought about it for a long time. I'd like to graduate.”</p></div></div><div class="row"><button class="b p" onclick="ctGradDlg(${m.id},'req')">Accept and plan the graduation</button><button class="b" onclick="ctPersuade(${m.id})">Try to persuade her to stay</button><button class="b s" onclick="ui.mod=null;render()">Later</button></div><p class="st">If nothing is decided, she announces her graduation herself 30 days after asking.</p>`}
function ctPersuade(mid){const m=get(mid);if(!m||!m.req)return;if(m.req.tried)return toast('You already tried once.','err');m.req.tried=1;if(Math.random()<cl(.2+(m.loy-50)/120,.05,.7)){m.req=null;hev(m,{t:'ct_stay'});ctLog(m,'stay','Decided to stay after a talk');ui.mod={t:'html',h:`<h2 class="ht">${esc(m.name)} stays</h2><p class="ctsay">“You're right. I'll keep going a little longer!”</p>`}}else{m.mor=cl(m.mor-5);ui.mod={t:'html',h:`<h2 class="ht">${esc(m.name)} has made up her mind</h2><p class="ctsay">“Thank you, but my decision won't change.”</p>${ctReqHtml(m).replace(/<h2[\s\S]*?<\/div><\/div>/,'')}`}}render()}
function ctBdProc(m){const Y=ctY(S.day);if(!m||!m.bd)return;if(ctBdDay(m,Y)==S.day&&m.bdY!=Y){m.age++;m.bdY=Y;hev(m,{t:'bday',age:m.age});ctLog(m,'bday',`Turned ${m.age}`);CTQ.push(`<div class="ctbd">🎂 <b>${esc(m.name)}</b> turns <b>${m.age}</b> today (${CT_MON[m.bd.mo-1]} ${m.bd.d}).</div>`)}}
