function ctTick(){const C=ctS(),Y=ctY(S.day);
 S.members.slice().forEach(m=>{try{ctEnsure(m);
  // birthday (age +1 once a year) and 7-day notice
  ctBdProc(m);
  const nb=ctNextBd(m);if(nb>S.day&&nb-S.day<=7&&m.bdN!=ctY(nb)){m.bdN=ctY(nb);CTQ.push(`<div class="ctbd">🎈 Upcoming birthday: <b>${esc(m.name)}</b> · ${longDate(nb)} · now ${m.age} → turns ${m.age+1}. <button class="b s" onclick="ui.mod=null;spPlan(${m.id},'bd')">Plan a Birthday Stage</button></div>`)}
  const c=m.ct;
  if(c.next&&S.day>=c.end){Object.assign(c,{type:c.next.type,yrs:c.next.yrs,age:c.next.age,start:c.end,end:c.next.end});c.next=null;c.talk=null;hev(m,{t:'ct_start',end:c.end});ctLog(m,'start',`New contract term started (until ${longDate(c.end)})`)}
  if(!m.grad&&!c.next){const left=c.end-S.day;
   if(left<=90&&(!c.talk||c.talk.end!=c.end)){c.talk={day:S.day,end:c.end,int:ctIntent(m),tries:0,res:null};hev(m,{t:'ct_talk'});ctLog(m,'talk',`Contract expiring on ${longDate(c.end)}: ${CT_INT[c.talk.int]}`);CTQ.push(`<div class="ctbd">📄 <b>${esc(m.name)}</b>'s contract ends on ${longDate(c.end)} (3 months). She ${CT_INT[c.talk.int]}. <button class="b s p" onclick="ui.mod=null;ctTalkOpen(${m.id})">Talk with her</button></div>`)}
   else if(left<=60&&c.talk&&!c.talk.res){ctAnnounce(m,{reason:'exp',target:Math.max(S.day+14,c.end),quiet:1})}}
  // member requests come from the motivation system (grad3.js)
  if(m.req&&!m.grad&&S.day-m.req.day>=30)ctAnnounce(m,{reason:'req',target:S.day+90,early:S.day+90<c.end-30?'ret':null,quiet:1});
 }catch(e){console.error('ct',m&&m.id,e)}});
 // careers one month after leaving; Agency Retained → Graduated at the contract end
 (S.alumni||[]).forEach(m=>{try{if(m.dep&&m.dep.ret&&m.ct&&S.day==m.ct.end){hev(m,{t:'ct_retend'});ctLog(m,'retend','Agency Retained period ended')}
  if(m.career&&!m.career.v&&S.day>=m.career.due)ctCareer(m)}catch(e){console.error(e)}});
 C.acts.forEach(a=>{try{ctActTick(a)}catch(e){console.error(e)}})}
{const f=tick;tick=function(){const r=f.apply(this,arguments);try{if(S)ctTick()}catch(e){console.error(e)}return r}}
