function ctCareer(m){const D=m.dep||{},bad=D.kind=='dismiss'&&D.dis&&D.dis.just;if(!bad&&!m.career.asked&&Math.random()<.12+(m.pop||0)/250){m.career.asked=1;m.career.due=S.day+7;CTQ.push(`<div class="ctbd">🎤 <b>${esc(m.name)}</b> (former member) proposes a <b>Solo Idol</b> career with your agency. <button class="b s p" onclick="ui.mod=null;ctSoloSign(${m.id},1)">Approve and sign</button><button class="b s" onclick="ui.mod=null;ctCareerSet(${m.id})">Reject</button></div>`);return}
 ctCareerSet(m.id)}
function ctCareerSet(mid,v){const m=ctMem(mid);if(!m||!m.career||m.career.v)return;if(!v){const W=[['ret',30],['ind',18],['new',22],['ag',m.dep&&m.dep.kind=='dismiss'?8:16+(m.pop||0)/8],['und',14]];let t=Math.random()*W.reduce((a,b)=>a+b[1],0);v=W.find(w=>(t-=w[1])<0)[0]}
 m.career.v=v;m.career.day=S.day;hev(m,{t:'ct_career',v:CT_CAR[v]});ctLog(m,'career',`Career: ${CT_CAR[v]}`);if(v!='solo'&&v!='grp')CTQ.push(`<div class="ctbd">🌱 Former member <b>${esc(m.name)}</b>: ${CT_CAR[v]}.</div>`);render()}
const CT_JOIN={ret:.25,ind:.55,new:.3,und:.5,null:.75,undefined:.75};
function ctSoloSign(mid,prop){const m=ctMem(mid);if(!m||S.members.includes(m))return;const cv=m.career&&m.career.v;if(['solo','grp','ag'].includes(cv))return toast(`${m.name} is not available (${CT_CAR[cv]}).`,'err');if(m.dep&&m.dep.ret&&S.day<m.ct.end)return toast(`${m.name} is Agency Retained until ${longDate(m.ct.end)} (no entertainment work).`,'err');
 if(!prop&&Math.random()>CT_JOIN[cv]){m.career=m.career||{due:S.day,v:null};m.career.inv=S.day;toast(`${m.name} declined the invitation.`,'err');ctLog(m,'inv','Declined a solo invitation');return render()}
 const a=ctActNew('solo',[m.id],m.stage||m.name);toast(`${m.name} signed a solo contract: “${a.name}”.`);render()}
